1	import { create } from "@bufbuild/protobuf";
2	import { FieldMaskSchema } from "@bufbuild/protobuf/wkt";
3	import copy from "copy-to-clipboard";
4	import { CheckIcon, CopyIcon, EyeIcon } from "lucide-react";
5	import React, { useEffect, useState } from "react";
6	import { toast } from "react-hot-toast";
7	import { Button } from "@/components/ui/button";
8	import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
9	import { Input } from "@/components/ui/input";
10	import { Label } from "@/components/ui/label";
11	import { userServiceClient } from "@/connect";
12	import useCurrentUser from "@/hooks/useCurrentUser";
13	import useLoading from "@/hooks/useLoading";
14	import { handleError } from "@/lib/error";
15	import { useTranslate } from "@/utils/i18n";
16	
17	interface Props {
18	  open: boolean;
19	  onOpenChange: (open: boolean) => void;
20	  webhookName?: string;
21	  onSuccess?: () => void;
22	}
23	
24	interface State {
25	  displayName: string;
26	  url: string;
27	}
28	
29	function CreateWebhookDialog({ open, onOpenChange, webhookName, onSuccess }: Props) {
30	  const t = useTranslate();
31	  const currentUser = useCurrentUser();
32	  const isCreating = webhookName === undefined;
33	  const [state, setState] = useState<State>({ displayName: "", url: "" });
34	  const requestState = useLoading(false);
35	  const secretState = useLoading(false);
36	  const [hasExistingSecret, setHasExistingSecret] = useState(false);
37	  const [revealedSecret, setRevealedSecret] = useState<string | undefined>(undefined);
38	  const [createdSecret, setCreatedSecret] = useState<string | undefined>(undefined);
39	  const [secretCopied, setSecretCopied] = useState(false);
40	
41	  useEffect(() => {
42	    if (webhookName && currentUser) {
43	      userServiceClient
44	        .listUserWebhooks({
45	          parent: currentUser.name,
46	        })
47	        .then((response) => {
48	          const webhook = response.webhooks.find((w) => w.name === webhookName);
49	          if (webhook) {
50	            setState({ displayName: webhook.displayName, url: webhook.url });
51	            setHasExistingSecret(webhook.signingSecretSet);
52	          }
53	        });
54	    }
55	  }, [webhookName, currentUser]);
56	
57	  useEffect(() => {
58	    if (open && isCreating) {
59	      setState({ displayName: "", url: "" });
60	      setHasExistingSecret(false);
61	      setRevealedSecret(undefined);
62	      setCreatedSecret(undefined);
63	      setSecretCopied(false);
64	    }
65	  }, [open, isCreating]);
66	
67	  const handleTitleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
68	    setState((prev) => ({ ...prev, displayName: e.target.value }));
69	  };
70	
71	  const handleUrlInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
72	    setState((prev) => ({ ...prev, url: e.target.value }));
73	  };
74	
75	  const handleCopySecret = (secret: string) => {
76	    copy(secret);
77	    setSecretCopied(true);
78	    setTimeout(() => setSecretCopied(false), 2000);
79	  };
80	
81	  const handleRevealSecret = async () => {
82	    if (!webhookName) return;
83	    try {
84	      secretState.setLoading();
85	      const { signingSecret } = await userServiceClient.getUserWebhookSigningSecret({ name: webhookName });
86	      setRevealedSecret(signingSecret);
87	      secretState.setFinish();
88	    } catch (error: unknown) {
89	      handleError(error, toast.error, { context: "Reveal signing secret", onError: () => secretState.setError() });
90	    }
91	  };
92	
93	  // Lets a pre-existing webhook that has no secret adopt one. The secret is
94	  // persisted immediately and revealed so the user can copy it once.
95	  const handleGenerateSecret = async () => {
96	    if (!webhookName) return;
97	    const bytes = crypto.getRandomValues(new Uint8Array(32));
98	    const secret = "whsec_" + btoa(String.fromCharCode(...bytes));
99	    try {
100	      secretState.setLoading();
101	      await userServiceClient.updateUserWebhook({
102	        webhook: { name: webhookName, signingSecret: secret },
103	        updateMask: create(FieldMaskSchema, { paths: ["signing_secret"] }),
104	      });
105	      setHasExistingSecret(true);
106	      setRevealedSecret(secret);
107	      handleCopySecret(secret);
108	      secretState.setFinish();
109	    } catch (error: unknown) {
110	      handleError(error, toast.error, { context: "Generate signing secret", onError: () => secretState.setError() });
111	    }
112	  };
113	
114	  // When closing after a successful create, refresh the parent list regardless of how the dialog is dismissed.
115	  const handleOpenChange = (next: boolean) => {
116	    if (!next && createdSecret !== undefined) {
117	      onSuccess?.();
118	    }
119	    onOpenChange(next);
120	  };
121	
122	  const handleSaveBtnClick = async () => {
123	    if (!state.displayName || !state.url) {
124	      toast.error(t("message.fill-all-required-fields"));
125	      return;
126	    }
127	
128	    if (!currentUser) {
129	      toast.error("User not authenticated");
130	      return;
131	    }
132	
133	    try {
134	      requestState.setLoading();
135	      if (isCreating) {
136	        // The signing secret is generated server-side; reveal it once so the user can copy it without reopening.
137	        const created = await userServiceClient.createUserWebhook({
138	          parent: currentUser.name,
139	          webhook: { displayName: state.displayName, url: state.url },
140	        });
141	        let secret: string | undefined;
142	        try {
143	          const response = await userServiceClient.getUserWebhookSigningSecret({ name: created.name });
144	          secret = response.signingSecret;
145	        } catch {
146	          // Reveal failed — the secret is still set and can be revealed later from the edit dialog.
147	        }
148	        requestState.setFinish();
149	        if (secret !== undefined) {
150	          setCreatedSecret(secret);
151	          return;
152	        }
153	        onSuccess?.();
154	        onOpenChange(false);
155	        return;
156	      }
157	
158	      await userServiceClient.updateUserWebhook({
159	        webhook: { name: webhookName, displayName: state.displayName, url: state.url },
160	        updateMask: create(FieldMaskSchema, { paths: ["display_name", "url"] }),
161	      });
162	      onSuccess?.();
163	      onOpenChange(false);
164	      requestState.setFinish();
165	    } catch (error: unknown) {
166	      handleError(error, toast.error, {
167	        context: webhookName ? "Update webhook" : "Create webhook",
168	        onError: () => requestState.setError(),
169	      });
170	    }
171	  };
172	
173	  const renderSecretField = (secret: string) => (
174	    <div className="flex items-center gap-2">
175	      <Input readOnly type="text" value={secret} className="flex-1 font-mono text-xs" />
176	      <Button
177	        type="button"
178	        variant="outline"
179	        size="icon"
180	        onClick={() => handleCopySecret(secret)}
181	        aria-label={t("setting.webhook.create-dialog.copy-secret")}
182	      >
183	        {secretCopied ? <CheckIcon className="h-4 w-4 text-success" /> : <CopyIcon className="h-4 w-4" />}
184	      </Button>
185	    </div>
186	  );
187	
188	  const renderSigningSecret = () => {
189	    if (isCreating) {
190	      return <span className="text-xs text-muted-foreground">{t("setting.webhook.create-dialog.signing-secret-auto-note")}</span>;
191	    }
192	    if (revealedSecret !== undefined) {
193	      return renderSecretField(revealedSecret);
194	    }
195	    if (hasExistingSecret) {
196	      return (
197	        <div className="flex items-center gap-2">
198	          <span className="flex-1 text-xs text-muted-foreground">{t("setting.webhook.create-dialog.signing-secret-configured")}</span>
199	          <Button type="button" variant="outline" size="sm" onClick={handleRevealSecret} disabled={secretState.isLoading}>
200	            <EyeIcon className="mr-1 h-3.5 w-3.5" />
201	            {t("setting.webhook.create-dialog.reveal-secret")}
202	          </Button>
203	        </div>
204	      );
205	    }
206	    return (
207	      <div className="flex items-center gap-2">
208	        <span className="flex-1 text-xs text-muted-foreground">{t("setting.webhook.create-dialog.signing-secret-not-configured")}</span>
209	        <Button type="button" variant="outline" size="sm" onClick={handleGenerateSecret} disabled={secretState.isLoading}>
210	          {t("setting.webhook.create-dialog.generate-secret")}
211	        </Button>
212	      </div>
213	    );
214	  };
215	
216	  return (
217	    <Dialog open={open} onOpenChange={handleOpenChange}>
218	      <DialogContent className="max-w-md">
219	        <DialogHeader>
220	          <DialogTitle>
221	            {isCreating ? t("setting.webhook.create-dialog.create-webhook") : t("setting.webhook.create-dialog.edit-webhook")}
222	          </DialogTitle>
223	        </DialogHeader>
224	        {createdSecret !== undefined ? (
225	          <div className="grid gap-2">
226	            <Label>{t("setting.webhook.create-dialog.signing-secret")}</Label>
227	            <span className="text-xs text-muted-foreground">{t("setting.webhook.create-dialog.signing-secret-created-note")}</span>
228	            {renderSecretField(createdSecret)}
229	          </div>
230	        ) : (
231	          <div className="flex flex-col gap-4">
232	            <div className="grid gap-2">
233	              <Label htmlFor="displayName">
234	                {t("setting.webhook.create-dialog.title")} <span className="text-destructive">*</span>
235	              </Label>
236	              <Input
237	                id="displayName"
238	                type="text"
239	                placeholder={t("setting.webhook.create-dialog.an-easy-to-remember-name")}
240	                value={state.displayName}
241	                onChange={handleTitleInputChange}
242	              />
243	            </div>
244	            <div className="grid gap-2">
245	              <Label htmlFor="url">
246	                {t("setting.webhook.create-dialog.payload-url")} <span className="text-destructive">*</span>
247	              </Label>
248	              <Input
249	                id="url"
250	                type="text"
251	                placeholder={t("setting.webhook.create-dialog.url-example-post-receive")}
252	                value={state.url}
253	                onChange={handleUrlInputChange}
254	              />
255	            </div>
256	            <div className="grid gap-2">
257	              <Label>{t("setting.webhook.create-dialog.signing-secret")}</Label>
258	              {renderSigningSecret()}
259	            </div>
260	          </div>
261	        )}
262	        <DialogFooter>
263	          {createdSecret !== undefined ? (
264	            <Button onClick={() => handleOpenChange(false)}>{t("common.close")}</Button>
265	          ) : (
266	            <>
267	              <Button variant="ghost" disabled={requestState.isLoading} onClick={() => onOpenChange(false)}>
268	                {t("common.cancel")}
269	              </Button>
270	              <Button disabled={requestState.isLoading} onClick={handleSaveBtnClick}>
271	                {isCreating ? t("common.create") : t("common.save")}
272	              </Button>
273	            </>
274	          )}
275	        </DialogFooter>
276	      </DialogContent>
277	    </Dialog>
278	  );
279	}
