3	import (
4		"bytes"
5		"context"
6		"crypto/hmac"
7		"crypto/rand"
8		"crypto/sha256"
9		"encoding/base64"
10		"encoding/json"
11		"io"
12		"log/slog"
13		"net"
14		"net/http"
15		"strconv"
16		"strings"
