20	func (s *APIV1Service) ListUserWebhooks(ctx context.Context, request *v1pb.ListUserWebhooksRequest) (*v1pb.ListUserWebhooksResponse, error) {
21		user, err := s.resolveUserFromName(ctx, request.Parent)
22		if err != nil {
23			return nil, status.Errorf(codes.InvalidArgument, "invalid parent: %v", err)
24		}
